#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned int u32;

int n, m;

// BIT for range add / point query (via difference), over long long
struct BIT {
    int n; vector<ll> t;
    void init(int n_){ n=n_; t.assign(n+2,0); }
    void add(int i, ll v){ for(;i<=n;i+=i&-i) t[i]+=v; }
    ll sum(int i){ ll s=0; for(;i>0;i-=i&-i) s+=t[i]; return s; }
};
BIT bitS, bitI; // slope, intercept

// add ramp: add v to a on [p,q]  =>  Delta P as derived
void addRamp(int p, int q, ll v){
    if(p>q) return;
    // slope += v on [p,q]
    bitS.add(p, v); if(q+1<=n) bitS.add(q+1, -v);
    // intercept += v*(1-p) on [p,q]
    ll B = v*(1-(ll)p);
    bitI.add(p, B); if(q+1<=n) bitI.add(q+1, -B);
    // intercept += v*q on [q+1,n]
    if(q+1<=n){ bitI.add(q+1, v*(ll)q); }
}
ll getP(int x){ // prefix sum a[1..x]
    ll s = bitS.sum(x);
    ll c = bitI.sum(x);
    return s*(ll)x + c;
}

map<int,ll> amap; // a intervals
map<int,ll> bmap; // b intervals

void splitA(int x){
    if(x>n) return;
    auto it = amap.upper_bound(x); --it;
    if(it->first == x) return;
    amap[x] = it->second;
}
void splitB(int x){
    if(x>n) return;
    auto it = bmap.upper_bound(x); --it;
    if(it->first == x) return;
    bmap[x] = it->second;
}

void assignA(int l,int r,ll x){
    splitA(l); splitA(r+1);
    auto it = amap.find(l);
    while(it != amap.end() && it->first <= r){
        int st = it->first;
        ll w = it->second;
        auto nit = next(it);
        int en = (nit==amap.end())? n : nit->first-1;
        // st>=l and en<=r
        addRamp(st, en, -w);
        it = amap.erase(it);
    }
    addRamp(l, r, x);
    amap[l] = x;
    // merge with next
    auto nx = amap.lower_bound(l);
    auto nx2 = next(nx);
    if(nx2!=amap.end() && nx2->second==x) amap.erase(nx2);
    // merge with prev
    auto cur = amap.find(l);
    if(cur!=amap.begin()){
        auto pv = prev(cur);
        if(pv->second==x) amap.erase(cur);
    }
}

void assignB(int l,int r,ll y){
    splitB(l); splitB(r+1);
    bmap.erase(bmap.find(l), bmap.upper_bound(r));
    auto it = bmap.lower_bound(l);
    if(it!=bmap.end() && it->second==y) bmap.erase(it);
    bmap[l]=y;
    auto cur=bmap.find(l);
    if(cur!=bmap.begin()){
        auto pv=prev(cur);
        if(pv->second==y) bmap.erase(cur);
    }
}

